head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf00200.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#paging7 table:first-child').attr('align', 'center');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00200.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(notice#searchfaqlist vs notice#searchfaqspec) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_srchWord_onkeydown
 * @description ipt_srchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_srchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode===13){$c.str.replaceAll(selfVar);await scwin.searchFaqListByCond();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00200.ipt_srchWord_onkeydown' }); }
};

/**
 * @method
 * @name ipt_srchWord_onblur
 * @description ipt_srchWord 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_srchWord_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00200.ipt_srchWord_onblur' }); }
};

/**
 * @method
 * @name btn_searchFaqListByCond_onclick
 * @description btn_searchFaqListByCond 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchFaqListByCond_onclick = async function(e){
    try {
        await scwin.searchFaqListByCond()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00200.btn_searchFaqListByCond_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchFaqSpec(r["contnId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name span_49_onclick
 * @description 「닫 기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.span_49_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00200.span_49_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_45_onclick
 * @description krxpage_pagenavigator_45 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_45_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchFaqListByCondReq').set('pageIndex', pi);
        await scwin.searchFaqListByCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf00200.krxpage_pagenavigator_45_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchFaqListByCond
 * @description search Faq List By Cond 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFaqListByCond = async function () {
    const sbmOptions = {
        id: "tx_fn_searchFaqListByCond",
        method: "post",
        action: "/main/notice.do?method=searchFaqList",
        ref: "dma_searchFaqListByCondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchFaqSpec
 * @description search Faq Spec 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchFaqSpec = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchFaqSpec",
        method: "post",
        action: action ?? "/main/notice.do?method=searchFaqSpec",
        ref: "dma_searchFaqSpecReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchFaqListByCondReq').set('pageIndex', "1");
};

/**
 * @method
 * @name searchFaqListByCond
 * @description search Faq List By Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFaqListByCond = async function () {
    const width = 670;
    const height = 500;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    _previewWindow = $c.win.openPopup("/notice/notice.xml", { id: "popFaqList", resizable: false, scrollbars: true, type: "pageFramePopup" }, ($c.util.getComponent("dma_searchFaqListByCondReq") ? $c.util.getComponent("dma_searchFaqListByCondReq").getJSON() : {}));
    const fm = (document.searchForm || { elements: [] });
    const clssTpCd = $("#clssTpCd option:selected").val();
    const srchDiv = $("#srchDiv option:selected").val();
    $c.util.getComponent("dma_searchFaqListByCondReq").set("clssTpCd", clssTpCd);
    $c.util.getComponent("dma_searchFaqListByCondReq").set("srchDiv", srchDiv);
    fm.action = '/main/notice.do?method=searchFaqList';

    return;
};

/**
 * @method
 * @name searchFaqSpec
 * @description search Faq Spec 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchFaqSpec = async function (contnId) {
    $c.util.getComponent('dma_searchFaqListByCondReq').set('contnId', contnId);
    await scwin.tx_fn_searchFaqSpec('/main/notice.do?method=searchFaqSpec');
    return;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
